    if (isAwait && !isAwaitUsingAllowed(context)) parser.report(Errors.AwaitUsingOutsideAsync);
    if ((origin & Origin.ForStatement) === 0 && (context & Context.InGlobal) && (context & Context.Module) === 0) {
