      parser.report(Errors.UsingDeclarationDestructuring);
    }
    if (parser.getToken() === Token.UsingKeyword) parser.report(Errors.KeywordNotId);

    const declarations = parseVariableDeclarationList(parser, context, scope, privateScope, BindingKind.Using, origin);
    matchOrInsertSemicolon(parser, context | Context.AllowRegExp);

    return parser.finishNode<ESTree.VariableDeclaration>(
