function summarize(ast) {
  // walk and collect VariableDeclaration kinds + node types
  const out = [];
  function walk(n) {
    if (!n || typeof n !== 'object') return;
    if (Array.isArray(n)) { n.forEach(walk); return; }
    if (n.type) {
