const require = createRequire('/app/');
const jiti = require('jiti')('/app', { interopDefault: true });
const { parseSource, Context } = jiti;

const lines = readFileSync('/tmp/case-list.txt', 'utf8').trim().split('\n');
const cases = [];
for (let i = 0; i < lines.length; i++) {
  const sep = lines[i].indexOf('|');
  const type = lines[i].slice(0, sep);
  let code = lines[i].slice(sep + 1);
  while (i + 1 < lines.length && !lines[i + 1].includes('|')) {
    i++;
    code += '\n' + lines[i];
  }
  cases.push({ type, code });
}

function v8Result(type, code) {
  try {
    if (type === 'S') {
      new vm.Script(code, { filename: 'test.js' });
    } else {
      new vm.SourceTextModule(code, { identifier: 'test.mjs' });
    }
    return { ok: true };
  } catch (e) {
    if (e instanceof SyntaxError) return { ok: false, msg: e.message };
    return { ok: false, msg: 'NON-SYNTAX: ' + e.constructor.name + ': ' + e.message };
  }
}

