+import { describe } from 'vitest';
+import { type Options } from '../../../src/options';
+import { fail, pass } from '../../test-utils';
+
+const next = (options: Options = {}): Options => ({ ...options, next: true });
+
+describe('Next - Using Declarations', () => {
+  pass('Using (pass)', [
+    // Module top level
+    { code: 'using x = 1;', options: next({ sourceType: 'module' }) },
+    { code: 'await using x = 1;', options: next({ sourceType: 'module' }) },
+    { code: 'if (true) { using x = 1; }', options: next({ sourceType: 'module' }) },
+    { code: 'if (true) { await using x = 1; }', options: next({ sourceType: 'module' }) },
+    { code: 'using x = 1, y = 2;', options: next({ sourceType: 'module' }) },
+    // Script: function and class bodies
+    { code: 'function f() { using x = 1; }', options: next() },
+    { code: 'async function f() { using x = 1; }', options: next() },
+    { code: 'async function f() { await using x = 1; }', options: next() },
+    { code: 'async function* f() { await using x = 1; }', options: next() },
+    { code: 'class C { async m() { await using x = 1; } }', options: next() },
+    { code: 'class C { static async m() { await using x = 1; } }', options: next() },
+    { code: 'const f = async () => { await using x = 1; }', options: next() },
+    { code: 'class C { static { using x = 1; } }', options: next() },
+    // For-of and for-await-of heads
+    { code: 'for (using x of y) z;', options: next() },
+    { code: 'for (using x = 1;;) z;', options: next() },
+    { code: 'async function f() { for (using x of y) z; }', options: next() },
+    { code: 'async function f() { for (await using x of y) z; }', options: next() },
+    { code: 'async function f() { for await (using x of y) z; }', options: next() },
+    { code: 'for (await using x of y) z;', options: next({ sourceType: 'module' }) },
+    { code: 'for await (using x of y) z;', options: next({ sourceType: 'module' }) },
+    // `using` is a contextual keyword and a valid identifier elsewhere
+    { code: 'using = 1;', options: next() },
+    { code: 'using(1);', options: next() },
+    { code: 'using;', options: next() },
+    { code: 'function f() { return using; }', options: next() },
+    { code: 'const x = [using];', options: next() },
+    { code: 'obj.using;', options: next() },
+    { code: 'var x = { using: 1 };', options: next() },
+    { code: 'let using = 1;', options: next() },
+    { code: 'var using;', options: next() },
+    { code: 'const using = 1;', options: next() },
+    { code: 'function using() {}', options: next() },
+    { code: 'function f(using = 1) {}', options: next() },
+    { code: 'const f = (using) => using;', options: next() },
+    { code: 'try {} catch (using) {}', options: next() },
+    { code: 'switch (a) { case using: break; }', options: next() },
+    { code: 'class C { using = 1; using() {} }', options: next() },
+    { code: 'import { using } from "x";', options: next({ sourceType: 'module' }) },
+    { code: 'import using from "x";', options: next({ sourceType: 'module' }) },
+    { code: 'import { using as u } from "x";', options: next({ sourceType: 'module' }) },
+    { code: 'export const using = 1;', options: next({ sourceType: 'module' }) },
+    // Labelled statement
+    { code: 'using: x = 1;', options: next() },
+    // Expression left-hand side in for-heads
+    { code: 'for (using of y) z;', options: next() },
+    { code: 'for (using in y) z;', options: next() },
+    // LineTerminator between `using` and the binding: identifier + ASI
+    { code: 'using\nx = 1;', options: next({ sourceType: 'module' }) },
+    { code: 'await using\nx = 1;', options: next({ sourceType: 'module' }) },
+  ]);
+
+  fail('Using (fail)', [
+    // Not allowed in the global scope of a script
+    { code: 'using x = 1;', options: next() },
+    { code: 'using x = 1;', options: next({ sourceType: 'commonjs' }) },
+    { code: 'if (true) { using x = 1; }', options: next() },
+    { code: 'while (false) { using x = 1; }', options: next() },
+    // `await using` outside async functions and module top level
+    // (reported before the script global scope error)
+    { code: 'await using x = 1;', options: next() },
+    { code: 'function f() { await using x = 1; }', options: next() },
+    { code: 'class C { m() { await using x = 1; } }', options: next() },
+    { code: 'if (true) { await using x = 1; }', options: next() },
+    { code: 'class C { static { await using x = 1; } }', options: next() },
+    { code: 'class C { static { await using x = 1; } }', options: next({ sourceType: 'module' }) },
+    { code: 'for (await using x of y) z;', options: next() },
+    // Missing initializer
+    { code: 'using x;', options: next({ sourceType: 'module' }) },
+    { code: 'function f() { using x; }', options: next() },
+    { code: 'async function f() { await using x; }', options: next() },
+    { code: 'function f() { using x of y; }', options: next() },
+    { code: 'function f() { using x in y; }', options: next() },
+    // Not allowed in for-in loops
+    { code: 'for (using x in y) z;', options: next() },
+    { code: 'for (using x = 1 in y) z;', options: next() },
+    { code: 'async function f() { for (await using x in y) z; }', options: next() },
+    // Destructuring patterns
+    { code: 'using [a] = x;', options: next({ sourceType: 'module' }) },
+    { code: 'using { a } = x;', options: next({ sourceType: 'module' }) },
+    { code: 'function f() { using [a] = x; }', options: next() },
+    { code: 'function f() { using { a } = x; }', options: next() },
+    { code: 'async function f() { await using [a] = x; }', options: next() },
+    // LineTerminator in the for-head
+    { code: 'for (using\nx of y) z;', options: next() },
+    { code: 'for (await using\nx of y) z;', options: next({ sourceType: 'module' }) },
+    { code: 'for (await\nusing x of y) z;', options: next({ sourceType: 'module' }) },
+  ]);
+
+  fail('Using (lexical, fail)', [
+    { code: 'function f() { using x = 1; let x = 2; }', options: next({ lexical: true }) },
+    { code: 'function f() { let x = 1; using x = 2; }', options: next({ lexical: true }) },
+    { code: 'function f() { var x; using x = 1; }', options: next({ lexical: true }) },
+  ]);
+});
